# works for 128x64 pixels in black & white
# image1 and image2 must have same size
# returns an array of pixel's coordinates to invert, after having displayed image1, to display image2
# numbers of this array are couples of bytes (uint8) : 1st byte for X coord and 2nd byte for Y 
def diff_image(image_data1, image_data2):
    if(len(image_data1) != len(image_data2)):
        print(f"Error: both images must have same size")
        return None
    diff_image = []
    count = 0
    # iterate on every byte of image
    for i in range(1, len(image_data1)):
        # iterate on every bit of current byte
        for j in range(8):
            img1_is_bit_set = (image_data1[i] & 1 << j) != 0
            img2_is_bit_set = (image_data2[i] & 1 << j) != 0
            #print(f"is_bit_set={is_bit_set}")
            if (img1_is_bit_set != img2_is_bit_set):
                x_coord = count % 128
                y_coord = round(count / 128)
                diff_image.append((x_coord, y_coord))
                print(f"bit changed for coords x={x_coord} y={y_coord}")
            count += 1
    return diff_image

